// Nó Code "Validar pedido do painel" (modo: executar uma vez para todos os itens).
// Recebe o corpo do Webhook { operacao, entrada } já autenticado por cabeçalho e
// decide a rota. Só passam as operações e os campos que o painel precisa.
// Cliente, editor e workflow de destino são fixos aqui: o chamador não escolhe.
// Rotas: 'recusa' | 'leitura' (lista de resumos) | 'leitura_trabalho' (um trabalho,
// sem trava) | 'leitura_pautas' (planos e fontes) | 'fila' (subworkflow 8zHU) |
// 'producao' (produtor Kk56) | 'fontes_async' / 'fontes_sync' (curadoria MafraFontesPauta) |
// 'enfileirador' (1Y2tf9mzggbGIpHZ).
const CLIENTES_PERMITIDOS = ['altovaletopteam_com_br'];
const EDITORES_PERMITIDOS = ['marcos_mafra'];
const AMBIENTES = ['producao', 'teste'];
const CAMPOS = {
  consultar: ['cliente_id', 'ambiente', 'job_key', 'cursor'],
  salvar_edicao: ['cliente_id', 'ambiente', 'job_key', 'op_id', 'revisao_esperada', 'artigo_sha256', 'markdown', 'ator_id'],
  decidir: ['cliente_id', 'ambiente', 'job_key', 'op_id', 'revisao_esperada', 'artigo_sha256', 'decisao', 'motivos', 'confirmo_revisao_editorial', 'pendencias_sha256', 'justificativa_pendencias', 'ator_id'],
  preparar_correcao: ['cliente_id', 'ambiente', 'job_key', 'op_id', 'revisao_esperada', 'artigo_sha256', 'autorizar_cobranca', 'ator_id'],
  retomar_producao: ['cliente_id', 'ambiente', 'job_key', 'revisao_esperada', 'autorizar_cobranca', 'ator_id'],
  ler_trabalho: ['cliente_id', 'ambiente', 'job_key'],
  ler_versao: ['cliente_id', 'ambiente', 'job_key', 'numero'],
  ler_resumos: ['cliente_id', 'ambiente'],
  listar_pautas: ['cliente_id'],
  propor_fontes: ['cliente_id', 'plano_cache_key', 'pauta_id', 'ator_id', 'autorizar_cobranca', 'urls_extras'],
  aprovar_fontes: ['cliente_id', 'plano_cache_key', 'pauta_id', 'ator_id'],
  enfileirar_pauta: ['cliente_id', 'ambiente', 'plano_cache_key', 'pauta_id', 'ator_id', 'op_id'],
};
const OBRIGATORIOS = {
  consultar: ['cliente_id', 'ambiente'],
  salvar_edicao: ['cliente_id', 'ambiente', 'job_key', 'op_id', 'revisao_esperada', 'artigo_sha256', 'markdown', 'ator_id'],
  decidir: ['cliente_id', 'ambiente', 'job_key', 'op_id', 'revisao_esperada', 'artigo_sha256', 'decisao', 'confirmo_revisao_editorial', 'ator_id'],
  preparar_correcao: ['cliente_id', 'ambiente', 'job_key', 'op_id', 'revisao_esperada', 'artigo_sha256', 'autorizar_cobranca', 'ator_id'],
  retomar_producao: ['cliente_id', 'ambiente', 'job_key', 'revisao_esperada', 'autorizar_cobranca', 'ator_id'],
  ler_trabalho: ['cliente_id', 'ambiente', 'job_key'],
  ler_versao: ['cliente_id', 'ambiente', 'job_key', 'numero'],
  ler_resumos: ['cliente_id', 'ambiente'],
  listar_pautas: ['cliente_id'],
  propor_fontes: ['cliente_id', 'plano_cache_key', 'pauta_id', 'ator_id', 'autorizar_cobranca'],
  aprovar_fontes: ['cliente_id', 'plano_cache_key', 'pauta_id', 'ator_id'],
  enfileirar_pauta: ['cliente_id', 'ambiente', 'plano_cache_key', 'pauta_id', 'ator_id', 'op_id'],
};
const MUTACOES = ['salvar_edicao', 'decidir', 'preparar_correcao'];
const ROTA = {
  ler_resumos: 'leitura',
  ler_trabalho: 'leitura_trabalho',
  ler_versao: 'leitura_trabalho',
  listar_pautas: 'leitura_pautas',
  retomar_producao: 'producao',
  propor_fontes: 'fontes_async',
  aprovar_fontes: 'fontes_sync',
  enfileirar_pauta: 'enfileirador',
};
const OPERACOES_DE_PAUTA = ['propor_fontes', 'aprovar_fontes', 'enfileirar_pauta'];

function recusa(codigo, mensagem) {
  return [{ json: { rota: 'recusa', http_status: 400, resposta: { ok: false, erro: { codigo, mensagem } } } }];
}
const hex64 = (v) => typeof v === 'string' && /^[a-f0-9]{64}$/.test(v);
const inteiroPositivo = (v) => Number.isSafeInteger(v) && v >= 1;

const itens = $input.all();
if (itens.length !== 1) return recusa('pedido_multiplo', 'Envie um pedido por chamada.');
const corpo = itens[0].json.body;
if (!corpo || typeof corpo !== 'object' || Array.isArray(corpo)) return recusa('corpo_invalido', 'Corpo ausente ou inválido.');
const extras = Object.keys(corpo).filter((k) => !['operacao', 'entrada'].includes(k));
if (extras.length) return recusa('campo_nao_permitido', 'Campos fora do envelope: ' + extras.join(', '));
const operacao = corpo.operacao;
if (!Object.prototype.hasOwnProperty.call(CAMPOS, operacao)) return recusa('operacao_nao_permitida', 'Operação não liberada para o painel.');
const e = corpo.entrada;
if (!e || typeof e !== 'object' || Array.isArray(e)) return recusa('entrada_invalida', 'Entrada ausente.');
const naoPermitidos = Object.keys(e).filter((k) => !CAMPOS[operacao].includes(k));
if (naoPermitidos.length) return recusa('campo_nao_permitido', 'Campos não permitidos: ' + naoPermitidos.join(', '));
const faltando = OBRIGATORIOS[operacao].filter((k) => e[k] === undefined || e[k] === null || e[k] === '');
if (faltando.length) return recusa('campo_obrigatorio', 'Campos obrigatórios ausentes: ' + faltando.join(', '));

if (!CLIENTES_PERMITIDOS.includes(e.cliente_id)) return recusa('cliente_nao_permitido', 'Cliente fora do escopo do painel.');
if (CAMPOS[operacao].includes('ambiente') && !AMBIENTES.includes(e.ambiente)) return recusa('ambiente_invalido', 'Ambiente inválido.');
if (e.job_key !== undefined && !hex64(e.job_key)) return recusa('chave_invalida', 'job_key inválida.');
if (e.cursor !== undefined && !(Number.isSafeInteger(e.cursor) && e.cursor >= 0)) return recusa('cursor_invalido', 'Cursor inválido.');
if (e.numero !== undefined && !inteiroPositivo(e.numero)) return recusa('versao_invalida', 'Número de versão inválido.');

if (MUTACOES.includes(operacao)) {
  if (!EDITORES_PERMITIDOS.includes(e.ator_id)) return recusa('editor_nao_autorizado', 'Ator não autorizado a editar ou decidir.');
  if (typeof e.op_id !== 'string' || !/^painel:[a-z0-9_]+:[A-Za-z0-9-]{8,80}$/.test(e.op_id) || !e.op_id.startsWith('painel:' + e.ator_id + ':')) {
    return recusa('op_id_invalido', 'op_id fora do formato do painel.');
  }
  if (!inteiroPositivo(e.revisao_esperada)) return recusa('revisao_invalida', 'revisao_esperada inválida.');
  if (!hex64(e.artigo_sha256)) return recusa('hash_invalido', 'artigo_sha256 inválido.');
}
if (OPERACOES_DE_PAUTA.includes(operacao)) {
  if (!EDITORES_PERMITIDOS.includes(e.ator_id)) return recusa('editor_nao_autorizado', 'Ator não autorizado a operar pautas.');
  if (typeof e.plano_cache_key !== 'string' || e.plano_cache_key.length > 250 || !e.plano_cache_key.startsWith('plano:' + e.cliente_id + ':')) return recusa('plano_invalido', 'Plano fora do cliente.');
  if (typeof e.pauta_id !== 'string' || !/^P\d{3,6}$/.test(e.pauta_id)) return recusa('pauta_invalida', 'Pauta inválida.');
}
if (operacao === 'propor_fontes') {
  if (e.autorizar_cobranca !== true) return recusa('cobranca_nao_autorizada', 'Autorização explícita de chamadas pagas ausente.');
  const extras = e.urls_extras === undefined ? [] : e.urls_extras;
  if (!Array.isArray(extras) || extras.length > 5 || !extras.every((u) => typeof u === 'string' && u.length <= 500 && /^https:\/\/[^\s/@:]+\/\S*$/.test(u))) {
    return recusa('urls_extras_invalidas', 'URLs extras inválidas (até 5, https).');
  }
}
if (operacao === 'enfileirar_pauta') {
  if (typeof e.op_id !== 'string' || !/^painel:[a-z0-9_]+:[A-Za-z0-9-]{8,80}$/.test(e.op_id) || !e.op_id.startsWith('painel:' + e.ator_id + ':')) {
    return recusa('op_id_invalido', 'op_id fora do formato do painel.');
  }
}
if (operacao === 'preparar_correcao' || operacao === 'retomar_producao') {
  // Etapas de agente podem gerar cobrança: só seguem com autorização explícita do editor.
  if (e.autorizar_cobranca !== true) return recusa('cobranca_nao_autorizada', 'Autorização explícita de chamadas pagas ausente.');
}
if (operacao === 'retomar_producao') {
  if (!EDITORES_PERMITIDOS.includes(e.ator_id)) return recusa('editor_nao_autorizado', 'Ator não autorizado a iniciar etapas.');
  if (!inteiroPositivo(e.revisao_esperada)) return recusa('revisao_invalida', 'revisao_esperada inválida.');
}
if (operacao === 'salvar_edicao') {
  if (typeof e.markdown !== 'string' || e.markdown.length < 200 || e.markdown.length > 800000) return recusa('markdown_invalido', 'O artigo precisa ter entre 200 e 800000 caracteres.');
}
if (operacao === 'decidir') {
  if (!['aprovar', 'devolver'].includes(e.decisao)) return recusa('decisao_invalida', 'Decisão deve ser aprovar ou devolver.');
  if (e.confirmo_revisao_editorial !== true) return recusa('confirmacao_ausente', 'Confirmação de revisão editorial ausente.');
  if (e.motivos !== undefined && !(Array.isArray(e.motivos) && e.motivos.length <= 20 && e.motivos.every((t) => typeof t === 'string' && t.trim().length >= 5 && t.length <= 3000))) {
    return recusa('motivos_invalidos', 'Motivos inválidos.');
  }
  if (e.decisao === 'devolver' && !(Array.isArray(e.motivos) && e.motivos.length > 0)) return recusa('devolucao_sem_motivos', 'Devolução exige ao menos um motivo.');
  if (e.pendencias_sha256 !== undefined && !hex64(e.pendencias_sha256)) return recusa('hash_invalido', 'pendencias_sha256 inválido.');
  if (e.justificativa_pendencias !== undefined && !(typeof e.justificativa_pendencias === 'string' && e.justificativa_pendencias.length <= 3000)) {
    return recusa('justificativa_invalida', 'Justificativa inválida.');
  }
}

const pedido = { operacao };
for (const k of CAMPOS[operacao]) if (e[k] !== undefined) pedido[k] = e[k];
return [{ json: { rota: ROTA[operacao] || 'fila', operacao, pedido } }];

// Nó Code "Formatar resposta da fila" — saída normal do subworkflow 8zHUZGYSA0nPhMWI.
const itens = $input.all();
if (itens.length !== 1) {
  return [{ json: { http_status: 200, resposta: { ok: false, erro: { codigo: 'resposta_inesperada_da_fila', mensagem: 'A fila devolveu ' + itens.length + ' itens.' } } } }];
}
const r = itens[0].json || {};
if (r.ok === false) {
  return [{ json: { http_status: 200, resposta: { ok: false, erro: { codigo: String(r.codigo || 'erro_da_fila'), mensagem: String(r.mensagem || r.codigo || 'A fila recusou a operação.').slice(0, 700) } } } }];
}
return [{ json: { http_status: 200, resposta: { ok: true, resultado: r } } }];

// Nó Code "Formatar falha da fila" — saída de erro do subworkflow (exceção não tratada).
const e = ($input.first() && $input.first().json) || {};
const bruto = e.error && typeof e.error === 'object' ? e.error.message || e.error.description : e.error || e.message;
const mensagem = String(bruto || 'O subworkflow da fila falhou.').slice(0, 700);
const codigo = /^[a-z_]{3,60}$/.test(mensagem) ? mensagem : 'falha_do_subworkflow';
return [{ json: { http_status: 200, resposta: { ok: false, erro: { codigo, mensagem } } } }];

// Nó Code "Leitura restrita da fila" (executar uma vez para todos os itens).
// Somente leitura. Recebe as linhas da Data Table já filtradas por cliente e
// ambiente, confere a integridade (payload_sha256) e devolve só o necessário:
//  - ler_resumos: títulos e datas de cada trabalho (a listagem oficial não traz);
//  - ler_versao: texto de uma versão anterior (a consulta oficial só traz a atual);
//  - ler_trabalho: o mesmo recibo de `consultar`, sem ocupar a trava global.
// Cópia literal da função sha256 usada pelos workflows da fila V2 (8zHUZGYSA0nPhMWI).
function sha256(text) {
  const bytes = Array.from(unescape(encodeURIComponent(text)), c => c.charCodeAt(0));
  const length = bytes.length * 8;
  bytes.push(128);
  while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i--) bytes.push(i >= 4 ? 0 : (length >>> (i * 8)) & 255);
  const k = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const h = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const rr = (v, n) => (v >>> n) | (v << (32 - n));
  for (let offset = 0; offset < bytes.length; offset += 64) {
    const w = [];
    for (let i = 0; i < 16; i++) w[i] = (bytes[offset+i*4]<<24)|(bytes[offset+i*4+1]<<16)|(bytes[offset+i*4+2]<<8)|bytes[offset+i*4+3];
    for (let i = 16; i < 64; i++) {
      const a = w[i-15], b = w[i-2];
      w[i] = (w[i-16] + (rr(a,7)^rr(a,18)^(a>>>3)) + w[i-7] + (rr(b,17)^rr(b,19)^(b>>>10))) | 0;
    }
    let [a,b,c,d,e,f,g,j] = h;
    for (let i = 0; i < 64; i++) {
      const t1 = (j + (rr(e,6)^rr(e,11)^rr(e,25)) + ((e&f)^(~e&g)) + k[i] + w[i]) | 0;
      const t2 = ((rr(a,2)^rr(a,13)^rr(a,22)) + ((a&b)^(a&c)^(b&c))) | 0;
      j=g; g=f; f=e; e=(d+t1)|0; d=c; c=b; b=a; a=(t1+t2)|0;
    }
    [a,b,c,d,e,f,g,j].forEach((v,i) => { h[i]=(h[i]+v)|0; });
  }
  return h.map(v => (v>>>0).toString(16).padStart(8,'0')).join('');
}


const pedido = $('Validar pedido do painel').first().json.pedido;
const linhas = $input.all().map((i) => i.json).filter((r) => r && r.id);

function carregar(row) {
  if (row.payload_sha256 !== sha256(row.payload_json || '')) return { erro: 'trabalho_alterado' };
  let j;
  try {
    j = JSON.parse(row.payload_json);
  } catch {
    return { erro: 'payload_ilegivel' };
  }
  if (j.versao !== 'editorial_markdown_v2' || j.job_key !== row.job_key || j.cliente_id !== row.cliente_id || j.ambiente !== row.ambiente) {
    return { erro: 'identidade_persistida_divergente' };
  }
  if (j.cliente_id !== pedido.cliente_id || j.ambiente !== pedido.ambiente) return { erro: 'isolamento_da_fila' };
  return { j };
}

function tituloH1(markdown) {
  if (typeof markdown !== 'string') return null;
  const m = markdown.match(/^#\s+(.+?)\s*#*\s*$/m);
  return m ? m[1].slice(0, 300) : null;
}

function responder(resposta) {
  return [{ json: { http_status: 200, resposta } }];
}

if (pedido.operacao === 'ler_resumos') {
  const resumos = [];
  const falhas = [];
  for (const row of linhas) {
    const r = carregar(row);
    if (r.erro) {
      falhas.push({ job_key: row.job_key, codigo: r.erro });
      continue;
    }
    const pauta = (r.j.pacote && r.j.pacote.research_input && r.j.pacote.research_input.pauta) || {};
    const atual = r.j.versoes[r.j.versoes.length - 1];
    resumos.push({
      job_key: r.j.job_key,
      titulo_pauta: typeof pauta.titulo === 'string' ? pauta.titulo.slice(0, 300) : null,
      intencao: typeof pauta.intencao === 'string' ? pauta.intencao : null,
      tema: typeof pauta.tema === 'string' ? pauta.tema.slice(0, 200) : null,
      titulo_artigo: atual ? tituloH1(atual.markdown) : null,
      modo_execucao: r.j.modo_execucao === 'simulado' ? 'simulado' : 'real',
      criado_em: r.j.criado_em || null,
      atualizado_em: r.j.atualizado_em || null,
    });
  }
  return responder({ ok: true, resultado: { resumos, falhas } });
}

// Mesmo recibo de `consultar` (qSummary da fila 8zHU), lido sem a trava global.
// A trava é compartilhada com o produtor: acompanhar uma etapa paga por `consultar`
// poderia ocupá-la no instante em que o produtor grava o resultado do agente.
const PROXIMA_ETAPA = { aguardando_briefing: 'pesquisador', aguardando_redacao: 'redator', aguardando_revisao: 'revisor' };

if (pedido.operacao === 'ler_trabalho') {
  const row = linhas.find((r) => r.job_key === pedido.job_key);
  if (!row) return responder({ ok: false, erro: { codigo: 'trabalho_nao_encontrado', mensagem: 'Trabalho não encontrado neste escopo.' } });
  const r = carregar(row);
  if (r.erro) return responder({ ok: false, erro: { codigo: r.erro, mensagem: 'Registro não passou na conferência de integridade.' } });
  const j = r.j;
  const v = j.versoes[j.versoes.length - 1];
  const decisao = j.decisoes[j.decisoes.length - 1];
  const aprovado = Boolean(
    j.controle && j.controle.aprovacao_editorial === true && decisao && decisao.decisao === 'aprovar' && v && decisao.artigo_sha256 === v.sha256 && decisao.versao_artigo === v.numero,
  );
  const pauta = (j.pacote && j.pacote.research_input && j.pacote.research_input.pauta) || {};
  const pendencias = Array.isArray(j.pendencias) ? j.pendencias : [];
  return responder({
    ok: true,
    resultado: {
      job_key: j.job_key,
      cliente_id: j.cliente_id,
      pauta_id: j.pauta_id,
      keyword: pauta.keyword,
      ambiente: j.ambiente,
      estado: j.estado,
      etapa: j.etapa,
      revisao: j.revisao,
      versao_artigo: v ? v.numero : 0,
      artigo_sha256: v ? v.sha256 : null,
      artigo_markdown: v ? v.markdown : null,
      decisao_atual: decisao || null,
      versoes: j.versoes.map(({ markdown, ...meta }) => meta),
      historico: j.historico,
      pendencias,
      pendencias_sha256: sha256(JSON.stringify(j.pendencias)),
      reserva: j.inflight ? { etapa: j.inflight.etapa, em: j.inflight.em, execucao_id: j.inflight.execucao_id } : null,
      chamadas_api_reservadas: j.chamadas_api_reservadas,
      chamadas_api_com_uso_confirmado: j.chamadas_api_com_uso_confirmado,
      controle: { aprovacao_editorial: aprovado, aprovacao_professor: false, publicacao_autorizada: false },
      executar_worker: false,
      chamadas_novas: 0,
      proxima_etapa: PROXIMA_ETAPA[j.estado] || null,
      retomada_bloqueada: Boolean(j.inflight || j.estado === 'resultado_incerto'),
      // Complementos que a consulta oficial não traz.
      leitura_sem_trava: true,
      modo_execucao: j.modo_execucao === 'simulado' ? 'simulado' : 'real',
      max_api_ciclo: Number.isSafeInteger(j.max_api_ciclo) ? j.max_api_ciclo : null,
      correcao_disponivel: Boolean(j.etapas && j.etapas.pesquisador),
      titulo_pauta: typeof pauta.titulo === 'string' ? pauta.titulo.slice(0, 300) : null,
      titulo_artigo: v ? tituloH1(v.markdown) : null,
      criado_em: j.criado_em || null,
      atualizado_em: j.atualizado_em || null,
    },
  });
}

if (pedido.operacao === 'ler_versao') {
  const row = linhas.find((r) => r.job_key === pedido.job_key);
  if (!row) return responder({ ok: false, erro: { codigo: 'trabalho_nao_encontrado', mensagem: 'Trabalho não encontrado neste escopo.' } });
  const r = carregar(row);
  if (r.erro) return responder({ ok: false, erro: { codigo: r.erro, mensagem: 'Registro não passou na conferência de integridade.' } });
  const v = r.j.versoes.find((x) => x.numero === pedido.numero);
  if (!v) return responder({ ok: false, erro: { codigo: 'versao_nao_encontrada', mensagem: 'Versão inexistente.' } });
  return responder({
    ok: true,
    resultado: {
      job_key: r.j.job_key,
      revisao: r.j.revisao,
